<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Ubuntu Desktop</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }

  html, body { width: 100%; height: 100%; overflow: hidden; }

  body {
    font-family: "Ubuntu", "Segoe UI", "Helvetica Neue", Arial, sans-serif;
    font-size: 14px;
    color: #f2f2f2;
    user-select: none;
  }

  /* ---------- Desktop ---------- */
  #desktop {
    position: fixed;
    inset: 0;
    background:
      radial-gradient(ellipse 120% 90% at 70% 10%, rgba(233,84,32,.35), transparent 55%),
      radial-gradient(ellipse 100% 80% at 15% 90%, rgba(119,33,111,.55), transparent 60%),
      linear-gradient(135deg, #2c001e 0%, #4a1042 45%, #77216f 75%, #963d8f 100%);
    overflow: hidden;
  }

  /* subtle noise-ish texture via layered gradients */
  #desktop::before {
    content: "";
    position: absolute; inset: 0;
    background-image:
      repeating-linear-gradient(45deg, rgba(255,255,255,.012) 0 2px, transparent 2px 6px);
    pointer-events: none;
  }

  /* ---------- Top bar ---------- */
  #topbar {
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 30px;
    background: rgba(20, 16, 20, .92);
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 14px;
    font-size: 13px;
    z-index: 5000;
    box-shadow: 0 1px 4px rgba(0,0,0,.4);
  }
  #topbar .tb-left  { display: flex; gap: 14px; align-items: center; }
  #topbar .tb-left b { font-weight: 500; }
  #topbar .tb-right { display: flex; gap: 12px; align-items: center; opacity: .9; }
  #clock { font-variant-numeric: tabular-nums; }

  /* ---------- Dock / Taskbar ---------- */
  #taskbar {
    position: absolute;
    left: 8px;
    top: 50%;
    transform: translateY(-50%);
    width: 64px;
    background: rgba(20, 16, 20, .78);
    backdrop-filter: blur(6px);
    border: 1px solid rgba(255,255,255,.08);
    border-radius: 14px;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 10px;
    padding: 12px 0;
    z-index: 5000;
    box-shadow: 0 4px 18px rgba(0,0,0,.45);
  }

  .launcher {
    width: 48px;
    height: 48px;
    border: none;
    border-radius: 12px;
    cursor: pointer;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    background: rgba(255,255,255,.06);
    color: #fff;
    transition: background .15s, transform .1s;
    position: relative;
  }
  .launcher:hover { background: rgba(255,255,255,.16); }
  .launcher:active { transform: scale(.93); }
  .launcher svg { width: 30px; height: 30px; display: block; }
  .launcher .tip {
    position: absolute;
    left: 58px;
    top: 50%;
    transform: translateY(-50%);
    background: rgba(20,16,20,.95);
    border: 1px solid rgba(255,255,255,.12);
    padding: 4px 10px;
    border-radius: 6px;
    font-size: 12px;
    white-space: nowrap;
    opacity: 0;
    pointer-events: none;
    transition: opacity .15s;
  }
  .launcher:hover .tip { opacity: 1; }
  .launcher.running::after {
    content: "";
    position: absolute;
    left: -7px;
    top: 50%;
    transform: translateY(-50%);
    width: 4px; height: 4px;
    border-radius: 50%;
    background: #e95420;
  }

  /* ---------- Windows ---------- */
  .app-window {
    position: absolute;
    min-width: 360px;
    min-height: 240px;
    width: 560px;
    height: 400px;
    background: #2b2b2e;
    border: 1px solid rgba(255,255,255,.1);
    border-radius: 10px;
    box-shadow: 0 14px 40px rgba(0,0,0,.55);
    display: flex;
    flex-direction: column;
    overflow: hidden;
    z-index: 100;
  }
  .app-window.hidden { display: none; }

  .titlebar {
    height: 38px;
    flex: 0 0 38px;
    background: linear-gradient(#3a3a3d, #313134);
    border-bottom: 1px solid rgba(0,0,0,.4);
    display: flex;
    align-items: center;
    padding: 0 10px;
    cursor: move;
    gap: 8px;
  }
  .titlebar .win-title {
    flex: 1;
    text-align: center;
    font-weight: 500;
    font-size: 13px;
    color: #ddd;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .titlebar .win-icon { width: 18px; height: 18px; flex: 0 0 18px; }

  .win-close {
    width: 22px;
    height: 22px;
    flex: 0 0 22px;
    border: none;
    border-radius: 50%;
    background: #e95420;
    color: #fff;
    font-size: 13px;
    line-height: 1;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: filter .12s;
  }
  .win-close:hover { filter: brightness(1.2); }

  .win-body {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-height: 0;
    background: #232326;
  }

  /* ---------- Files app ---------- */
  #files-toolbar {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 8px 10px;
    background: #2b2b2e;
    border-bottom: 1px solid rgba(255,255,255,.07);
    flex: 0 0 auto;
  }
  #files-up {
    border: 1px solid rgba(255,255,255,.14);
    background: rgba(255,255,255,.06);
    color: #eee;
    width: 30px; height: 28px;
    border-radius: 6px;
    cursor: pointer;
    font-size: 14px;
    transition: background .12s;
  }
  #files-up:hover:not(:disabled) { background: rgba(255,255,255,.15); }
  #files-up:disabled { opacity: .35; cursor: default; }
  #files-path {
    flex: 1;
    background: #1d1d20;
    border: 1px solid rgba(255,255,255,.1);
    border-radius: 6px;
    padding: 5px 10px;
    font-family: "Ubuntu Mono", Consolas, monospace;
    font-size: 13px;
    color: #d7c4d3;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  #files-list {
    flex: 1;
    overflow-y: auto;
    padding: 12px;
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(96px, 1fr));
    gap: 6px;
    align-content: start;
  }
  .fs-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 4px;
    padding: 10px 4px 8px;
    border-radius: 8px;
    cursor: pointer;
    text-align: center;
    font-size: 12.5px;
    word-break: break-word;
    color: #eee;
  }
  .fs-item:hover { background: rgba(255,255,255,.07); }
  .fs-item.selected { background: rgba(233,84,32,.32); }
  .fs-item svg { width: 44px; height: 44px; }
  .files-empty {
    grid-column: 1 / -1;
    color: #999;
    font-style: italic;
    padding: 20px;
    text-align: center;
  }

  #files-status {
    flex: 0 0 auto;
    padding: 5px 12px;
    font-size: 12px;
    color: #9a8f98;
    border-top: 1px solid rgba(255,255,255,.06);
    background: #26262a;
  }

  /* ---------- Notepad app ---------- */
  #notepad-window { width: 620px; height: 440px; }

  #tabbar-row {
    display: flex;
    align-items: stretch;
    background: #2b2b2e;
    border-bottom: 1px solid rgba(255,255,255,.08);
    flex: 0 0 auto;
  }
  #tabs {
    display: flex;
    flex: 1;
    overflow-x: auto;
    min-width: 0;
  }
  #tabs::-webkit-scrollbar { height: 4px; }
  .tab {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 8px 12px;
    max-width: 180px;
    min-width: 90px;
    font-size: 13px;
    color: #bbb;
    cursor: pointer;
    border-right: 1px solid rgba(255,255,255,.06);
    border-top: 2px solid transparent;
    white-space: nowrap;
    flex: 0 0 auto;
  }
  .tab:hover { background: rgba(255,255,255,.05); }
  .tab.active {
    background: #232326;
    color: #fff;
    border-top-color: #e95420;
  }
  .tab .tab-title {
    overflow: hidden;
    text-overflow: ellipsis;
    flex: 1;
  }
  .tab .tab-x {
    width: 16px; height: 16px;
    border: none;
    background: transparent;
    color: #999;
    border-radius: 4px;
    cursor: pointer;
    font-size: 12px;
    line-height: 1;
    padding: 0;
    flex: 0 0 16px;
  }
  .tab .tab-x:hover { background: rgba(255,255,255,.15); color: #fff; }
  #new-tab {
    flex: 0 0 auto;
    width: 34px;
    border: none;
    background: transparent;
    color: #ccc;
    font-size: 18px;
    cursor: pointer;
    transition: background .12s;
  }
  #new-tab:hover { background: rgba(255,255,255,.1); }

  #editor {
    flex: 1;
    width: 100%;
    resize: none;
    border: none;
    outline: none;
    background: #1d1d20;
    color: #eaeaea;
    padding: 12px 14px;
    font-family: "Ubuntu Mono", Consolas, "Courier New", monospace;
    font-size: 14px;
    line-height: 1.5;
    user-select: text;
  }

  #notepad-status {
    flex: 0 0 auto;
    padding: 5px 12px;
    font-size: 12px;
    color: #9a8f98;
    border-top: 1px solid rgba(255,255,255,.06);
    background: #26262a;
  }

  /* scrollbars */
  ::-webkit-scrollbar { width: 10px; height: 10px; }
  ::-webkit-scrollbar-track { background: transparent; }
  ::-webkit-scrollbar-thumb { background: rgba(255,255,255,.18); border-radius: 6px; }
  ::-webkit-scrollbar-thumb:hover { background: rgba(255,255,255,.3); }
</style>
</head>
<body>
<div id="desktop">

