<script>
(function () {
  "use strict";

  /* ================= Clock ================= */
  var clockEl = document.getElementById("clock");
  function tick() {
    var d = new Date();
    var days = ["Sun","Mon","Tue","Wed","Thu","Fri","Sat"];
    var months = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
    function p(n) { return n < 10 ? "0" + n : "" + n; }
    clockEl.textContent = days[d.getDay()] + " " + months[d.getMonth()] + " " +
      d.getDate() + "  " + p(d.getHours()) + ":" + p(d.getMinutes());
  }
  tick();
  setInterval(tick, 15000);

  /* ================= Window manager ================= */
  var zCounter = 200;

  function bringToFront(win) {
    zCounter += 1;
    win.style.zIndex = zCounter;
  }

  function makeDraggable(win) {
    var bar = win.querySelector(".titlebar");
    bar.addEventListener("mousedown", function (e) {
      if (e.target.closest(".win-close")) return;
      e.preventDefault();
      bringToFront(win);
      var startX = e.clientX, startY = e.clientY;
      var rect = win.getBoundingClientRect();
      var origL = rect.left, origT = rect.top;
      function move(ev) {
        var nl = origL + (ev.clientX - startX);
        var nt = origT + (ev.clientY - startY);
        nl = Math.max(-rect.width + 80, Math.min(nl, window.innerWidth - 80));
        nt = Math.max(30, Math.min(nt, window.innerHeight - 40));
        win.style.left = nl + "px";
        win.style.top = nt + "px";
      }
      function up() {
        document.removeEventListener("mousemove", move);
        document.removeEventListener("mouseup", up);
      }
      document.addEventListener("mousemove", move);
      document.addEventListener("mouseup", up);
    });
    win.addEventListener("mousedown", function () { bringToFront(win); });
  }

  function wireWindow(winId, launcherId, onShow) {
    var win = document.getElementById(winId);
    var launcher = document.getElementById(launcherId);
    makeDraggable(win);
    launcher.addEventListener("click", function () {
      win.classList.remove("hidden");
      launcher.classList.add("running");
      bringToFront(win);
      if (onShow) onShow();
    });
    win.querySelector(".win-close").addEventListener("click", function () {
      win.classList.add("hidden");
      launcher.classList.remove("running");
    });
  }

  /* ================= Files app ================= */
  // Folders are objects; files are strings (fake size labels).
  var FS = {
    "bin": { "bash": "1.2 MB", "cat": "35 KB", "cp": "141 KB", "ls": "138 KB", "mkdir": "84 KB", "mv": "147 KB", "rm": "72 KB", "sh": "125 KB" },
    "boot": { "grub": { "grub.cfg": "8 KB" }, "vmlinuz-6.8.0-generic": "14 MB", "initrd.img-6.8.0-generic": "104 MB" },
    "dev": { "null": "0 B", "random": "0 B", "sda": "0 B", "tty0": "0 B" },
    "etc": {
      "apt": { "sources.list": "2 KB" },
      "ssh": { "sshd_config": "3 KB" },
      "fstab": "1 KB", "hostname": "12 B", "hosts": "221 B", "passwd": "2 KB", "os-release": "386 B"
    },
    "home": {
      "user": {
        "Documents": {
          "notes.txt": "1 KB",
          "resume.pdf": "88 KB",
          "projects": { "todo.md": "2 KB", "ideas.md": "4 KB" }
        },
        "Downloads": { "ubuntu-24.04-desktop-amd64.iso": "5.7 GB", "wallpaper.jpg": "2.1 MB" },
        "Pictures": { "Screenshots": { "screenshot-01.png": "412 KB" }, "vacation.png": "3.4 MB", "cat.jpg": "1.8 MB" },
        "Music": {},
        "Videos": {},
        ".bashrc": "3 KB",
        ".profile": "807 B"
      }
    },
    "lib": { "systemd": { "systemd": "1.9 MB" }, "modules": {} },
    "opt": {},
    "proc": { "cpuinfo": "0 B", "meminfo": "0 B", "uptime": "0 B" },
    "root": {},
    "sbin": { "init": "43 KB", "fsck": "310 KB", "reboot": "27 KB" },
    "srv": {},
    "tmp": {},
    "usr": {
      "bin": { "python3": "6.8 MB", "gcc": "1.1 MB", "vim": "3.7 MB", "curl": "260 KB", "git": "3.9 MB" },
      "lib": {},
      "local": { "bin": {}, "share": {} },
      "share": { "doc": {}, "man": {}, "icons": {} }
    },
    "var": {
      "log": { "syslog": "4.2 MB", "auth.log": "812 KB", "kern.log": "1.6 MB" },
      "cache": { "apt": {} },
      "tmp": {},
      "www": { "html": { "index.html": "11 KB" } }
    }
  };

  var filesPath = [];   // array of segment names; [] = root
  var pathEl = document.getElementById("files-path");
  var listEl = document.getElementById("files-list");
  var upBtn = document.getElementById("files-up");
  var statusEl = document.getElementById("files-status");

  function currentDir() {
    var node = FS;
    for (var i = 0; i < filesPath.length; i++) node = node[filesPath[i]];
    return node;
  }

  var FOLDER_SVG = '<svg viewBox="0 0 24 24" fill="none">' +
    '<path d="M3 6a2 2 0 0 1 2-2h4l2 2h8a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6z" fill="#e8a33d"/>' +
    '<path d="M3 9h18v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V9z" fill="#f5c26b"/></svg>';
  var FILE_SVG = '<svg viewBox="0 0 24 24" fill="none">' +
    '<path d="M6 2h8l5 5v14a1 1 0 0 1-1 1H6a1 1 0 0 1-1-1V3a1 1 0 0 1 1-1z" fill="#e6e6e6"/>' +
    '<path d="M14 2v5h5" fill="#bdbdbd"/>' +
    '<path d="M8.5 12h7M8.5 15h7M8.5 18h4.5" stroke="#9a9a9a" stroke-width="1.2" stroke-linecap="round"/></svg>';

  function renderFiles() {
    pathEl.textContent = "/" + filesPath.join("/");
    upBtn.disabled = filesPath.length === 0;
    listEl.innerHTML = "";
    var dir = currentDir();
    var names = Object.keys(dir).sort(function (a, b) {
      var af = typeof dir[a] === "object", bf = typeof dir[b] === "object";
      if (af !== bf) return af ? -1 : 1;
      return a.localeCompare(b);
    });

    if (names.length === 0) {
      var empty = document.createElement("div");
      empty.className = "files-empty";
      empty.textContent = "This folder is empty";
      listEl.appendChild(empty);
    }

    var folders = 0, files = 0;
    names.forEach(function (name) {
      var isFolder = typeof dir[name] === "object";
      if (isFolder) folders++; else files++;
      var item = document.createElement("div");
      item.className = "fs-item";
      item.innerHTML = isFolder ? FOLDER_SVG : FILE_SVG;
      var label = document.createElement("span");
      label.textContent = name;
      item.appendChild(label);
      item.title = isFolder ? (name + " (folder)") : (name + " — " + dir[name]);

      item.addEventListener("click", function () {
        var prev = listEl.querySelector(".fs-item.selected");
        if (prev) prev.classList.remove("selected");
        item.classList.add("selected");
      });
      if (isFolder) {
        item.addEventListener("dblclick", function () {
          filesPath.push(name);
          renderFiles();
        });
      }
      listEl.appendChild(item);
    });
    statusEl.textContent = folders + " folder" + (folders === 1 ? "" : "s") +
      ", " + files + " file" + (files === 1 ? "" : "s");
  }

  upBtn.addEventListener("click", function () {
    if (filesPath.length > 0) {
      filesPath.pop();
      renderFiles();
    }
  });

  /* ================= Notepad app ================= */
  var STORAGE_KEY = "ubuntu-notepad-v1";
  var tabsEl = document.getElementById("tabs");
  var newTabBtn = document.getElementById("new-tab");
  var editor = document.getElementById("editor");
  var npStatus = document.getElementById("notepad-status");

  var state = { tabs: [], activeId: null, seq: 1 };

  function loadState() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (raw) {
        var parsed = JSON.parse(raw);
        if (parsed && Array.isArray(parsed.tabs) && parsed.tabs.length > 0) {
          state = parsed;
          if (!state.tabs.some(function (t) { return t.id === state.activeId; })) {
            state.activeId = state.tabs[0].id;
          }
          if (typeof state.seq !== "number") state.seq = state.tabs.length + 1;
          return;
        }
      }
    } catch (e) { /* corrupted storage — start fresh */ }
    var first = { id: "t1", title: "Untitled 1", content: "" };
    state = { tabs: [first], activeId: first.id, seq: 2 };
    saveState();
  }

  function saveState() {
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); } catch (e) {}
  }

  function activeTab() {
    for (var i = 0; i < state.tabs.length; i++) {
      if (state.tabs[i].id === state.activeId) return state.tabs[i];
    }
    return state.tabs[0] || null;
  }

  function renderTabs() {
    tabsEl.innerHTML = "";
    state.tabs.forEach(function (t) {
      var el = document.createElement("div");
      el.className = "tab" + (t.id === state.activeId ? " active" : "");
      el.setAttribute("data-id", t.id);

      var title = document.createElement("span");
      title.className = "tab-title";
      title.textContent = t.title;
      el.appendChild(title);

      var x = document.createElement("button");
      x.className = "tab-x";
      x.title = "Close tab";
      x.innerHTML = "&#10005;";
      x.addEventListener("click", function (e) {
        e.stopPropagation();
        closeTab(t.id);
      });
      el.appendChild(x);

      el.addEventListener("click", function () {
        state.activeId = t.id;
        saveState();
        renderTabs();
        renderEditor();
      });
      tabsEl.appendChild(el);
    });
    renderEditor();
  }

  function renderEditor() {
    var t = activeTab();
    editor.value = t ? t.content : "";
    updateStatus();
  }

  function updateStatus() {
    var t = activeTab();
    if (!t) { npStatus.textContent = ""; return; }
    var len = t.content.length;
    var lines = t.content.length ? t.content.split("\n").length : 1;
    npStatus.textContent = t.title + " — " + lines + " line" + (lines === 1 ? "" : "s") +
      ", " + len + " character" + (len === 1 ? "" : "s") + " (saved)";
  }

  function newTab() {
    var t = { id: "t" + state.seq, title: "Untitled " + state.seq, content: "" };
    state.seq += 1;
    state.tabs.push(t);
    state.activeId = t.id;
    saveState();
    renderTabs();
    editor.focus();
  }

  function closeTab(id) {
    var idx = state.tabs.findIndex(function (t) { return t.id === id; });
    if (idx === -1) return;
    state.tabs.splice(idx, 1);
    if (state.tabs.length === 0) {
      var t = { id: "t" + state.seq, title: "Untitled " + state.seq, content: "" };
      state.seq += 1;
      state.tabs.push(t);
    }
    if (state.activeId === id) {
      state.activeId = state.tabs[Math.min(idx, state.tabs.length - 1)].id;
    }
    saveState();
    renderTabs();
  }

  editor.addEventListener("input", function () {
    var t = activeTab();
    if (!t) return;
    t.content = editor.value;
    var firstLine = t.content.split("\n")[0].trim();
    if (firstLine) {
      t.title = firstLine.length > 18 ? firstLine.slice(0, 18) + "…" : firstLine;
    } else {
      t.title = "Untitled " + t.id.slice(1);
    }
    saveState();
    // update just the visible tab label + status (avoid full re-render mid-typing)
    var tabEl = tabsEl.querySelector('.tab[data-id="' + t.id + '"] .tab-title');
    if (tabEl) tabEl.textContent = t.title;
    updateStatus();
  });

  newTabBtn.addEventListener("click", newTab);

  /* ================= Boot ================= */
  loadState();
  renderTabs();
  renderFiles();

  wireWindow("files-window", "open-files", function () { renderFiles(); });
  wireWindow("notepad-window", "open-notepad", function () {
    loadState();      // re-sync with localStorage on every open
    renderTabs();
    editor.focus();
  });
})();
</script>
